(function mergeKotobaID(){
  const byJp = {};
  KOTOBA_ID_N5.forEach(e => { byJp[e.jp] = e; });
  KOTOBA_ID_N4.forEach(e => { byJp[e.jp] = e; });
  KOTOBA_ID_N3_B1.forEach(e => { byJp[e.jp] = e; });
  KOTOBA_ID_N3_B2.forEach(e => { byJp[e.jp] = e; });
  KOTOBA_ID_N3_B3.forEach(e => { byJp[e.jp] = e; });
  KOTOBA_ID_N3_B4.forEach(e => { byJp[e.jp] = e; });
  KOTOBA_ID_N3_B5.forEach(e => { byJp[e.jp] = e; });
  KOTOBA_ID_N3_B6.forEach(e => { byJp[e.jp] = e; });
  KOTOBA_ID_N2_B1.forEach(e => { byJp[e.jp] = e; });
  KOTOBA_ID_N2_B2.forEach(e => { byJp[e.jp] = e; });
  KOTOBA_ID_N2_B3.forEach(e => { byJp[e.jp] = e; });
  KOTOBA_ID_N2_B4.forEach(e => { byJp[e.jp] = e; });
  KOTOBA_ID_N2_B5.forEach(e => { byJp[e.jp] = e; });
  VOCAB.forEach(v => {
    if(v.type === "kotoba"){
      const e = byJp[v.jp];
      if(e){
        v.meaning_id = e.meaning_id;
        if(e.contoh_jp) v.contoh_jp = e.contoh_jp;
        if(e.contoh_id) v.contoh_id = e.contoh_id;
        // Cara baca (yomi): pakai yomi dari terjemahan kalau ada,
        // kalau tidak fallback ke field "romaji" bawaan VOCAB (index.html)
        // supaya kata2 lama (N5/N4/N3 batch 1-5) tetap tampil cara bacanya.
        v.yomi = e.yomi || v.romaji || "";
      } else if(v.romaji){
        v.yomi = v.romaji;
      }
    }
  });
})();

